// One row per article, with the search term kept on every row so a sheet
// covering several brands stays sortable.
const weekOf = $now.toFormat('yyyy-MM-dd');

const clip = (s, n) => {
  const v = String(s || '').replace(/\s+/g, ' ').trim();
  return v.length > n ? v.slice(0, n - 3) + '...' : v;
};

const rows = [];
for (const item of $input.all()) {
  const term = (item.json.search_parameters || {}).q || '';
  for (const a of item.json.news_results || []) {
    rows.push({
      json: {
        'Week of': weekOf,
        Watching: term,
        Rank: a.position ?? '',
        Headline: clip(a.title, 200),
        Source: a.source || '',
        Published: a.date || '',
        Snippet: clip(a.snippet, 400),
        Link: a.link || '',
      },
    });
  }
}
return rows;
